Падают тесты сервера (нет типов Jest) и мобильного клиента — сначала чиню конфиги Jest/TS, затем перепроверю.```json
{"version":1,"taskId":"a774d560-174b-4dd3-aa4b-e675234cf2f5","commandId":"fix-jest-1","operation":"run","headSha":"d0db4c9c0b6931d24eaa55511e7f39a729109667","timeoutSeconds":60,"command":"set -euo pipefail

# isolatedModules for NodeNext + ts-jest
node -e '
const fs=require("fs");
const p="tsconfig.base.json";
const j=JSON.parse(fs.readFileSync(p,"utf8"));
j.compilerOptions.isolatedModules=true;
fs.writeFileSync(p, JSON.stringify(j,null,2)+"\n");
'

cat > apps/server/tsconfig.jest.json <<'EOF'
{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "types": ["node", "jest"],
    "noEmit": true,
    "rootDir": ".",
    "isolatedModules": true
  },
  "include": ["src/**/*.ts", "__tests__/**/*.ts"]
}
EOF

cat > packages/shared/tsconfig.jest.json <<'EOF'
{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "types": ["jest"],
    "noEmit": true,
    "rootDir": ".",
    "isolatedModules": true
  },
  "include": ["src/**/*.ts", "__tests__/**/*.ts"]
}
EOF

cat > apps/server/jest.config.cjs <<'EOF'
/** @type {import('jest').Config} */
module.exports = {
  preset: 'ts-jest/presets/default-esm',
  testEnvironment: 'node',
  roots: ['<rootDir>/src', '<rootDir>/__tests__'],
  extensionsToTreatAsEsm: ['.ts'],
  moduleNameMapper: {
    '^(\\.{1,2}/.*)\\.js$': '$1',
    '^@msngr/shared$': '<rootDir>/../../packages/shared/src/index.ts',
  },
  transform: {
    '^.+\\.tsx?$': [
      'ts-jest',
      {
        useESM: true,
        tsconfig: '<rootDir>/tsconfig.jest.json',
        diagnostics: { ignoreCodes: [151002] },
      },
    ],
  },
};
EOF

cat > packages/shared/jest.config.cjs <<'EOF'
/** @type {import('jest').Config} */
module.exports = {
  preset: 'ts-jest/presets/default-esm',
  testEnvironment: 'node',
  roots: ['<rootDir>/src', '<rootDir>/__tests__'],
  extensionsToTreatAsEsm: ['.ts'],
  moduleNameMapper: {
    '^(\\.{1,2}/.*)\\.js$': '$1',
  },
  transform: {
    '^.+\\.tsx?$': [
      'ts-jest',
      {
        useESM: true,
        tsconfig: '<rootDir>/tsconfig.jest.json',
        diagnostics: { ignoreCodes: [151002] },
      },
    ],
  },
};
EOF

cat > apps/mobile/jest.config.cjs <<'EOF'
/** @type {import('jest').Config} */
module.exports = {
  preset: 'jest-expo',
  testMatch: ['**/__tests__/**/*.test.ts?(x)'],
  moduleNameMapper: {
    '^@msngr/shared$': '<rootDir>/../../packages/shared/src/index.ts',
  },
  transformIgnorePatterns: [
    'node_modules/(?!((jest-)?react-native|@react-native(-community)?)|expo(nent)?|@expo(nent)?/.*|@expo-google-fonts/.*|react-navigation|@react-navigation/.*|@sentry/react-native|native-base|react-native-svg)',
  ],
};
EOF

# show mobile failure detail first after fix attempt on server
npm test -w @msngr/server
npm test -w @msngr/shared
set +e
npm test -w @msngr/mobile
MOBILE_EC=$?
set -e
echo MOBILE_EXIT=$MOBILE_EC
"}
```

Жду `fix-jest-1` с деталями по mobile.

